begin
\gntv_or_sync_fifo.gcx.clkx\: entity work.clk_x_pntrs
     port map (
      AR(0) => rst_full_ff_i,
      D(2) => \gntv_or_sync_fifo.gl0.rd_n_7\,
      D(1) => \gntv_or_sync_fifo.gl0.rd_n_8\,
      D(0) => \gntv_or_sync_fifo.gl0.rd_n_9\,
      Q(3 downto 0) => wr_pntr_plus1(3 downto 0),
      \Q_reg_reg[0]\(0) => rd_rst_i(1),
      \gnxpm_cdc.rd_pntr_gc_reg[3]_0\(0) => rd_pntr(3),
      \gnxpm_cdc.wr_pntr_bin_reg[3]_0\(3 downto 0) => wr_pntr_rd(3 downto 0),
      \gnxpm_cdc.wr_pntr_gc_reg[3]_0\(3 downto 0) => wr_pntr(3 downto 0),
      \out\ => \gntv_or_sync_fifo.gl0.wr_n_1\,
      ram_full_fb_i_reg => \gntv_or_sync_fifo.gcx.clkx_n_0\,
      ram_full_fb_i_reg_0(3 downto 0) => wr_pntr_plus2(3 downto 0),
      rd_clk => rd_clk,
      wr_clk => wr_clk,
      wr_en => wr_en
    );
\gntv_or_sync_fifo.gl0.rd\: entity work.rd_logic
     port map (
      AR(0) => rd_rst_i(2),
      D(2) => \gntv_or_sync_fifo.gl0.rd_n_7\,
      D(1) => \gntv_or_sync_fifo.gl0.rd_n_8\,
      D(0) => \gntv_or_sync_fifo.gl0.rd_n_9\,
      E(0) => ram_rd_en_i,
      Q(3 downto 0) => rd_pntr(3 downto 0),
      empty => empty,
      ram_empty_i_reg(3 downto 0) => wr_pntr_rd(3 downto 0),
      rd_clk => rd_clk,
      rd_en => rd_en,
      underflow => underflow
    );
\gntv_or_sync_fifo.gl0.wr\: entity work.wr_logic
     port map (
      E(0) => ram_wr_en,
      Q(3 downto 0) => wr_pntr_plus2(3 downto 0),
      full => full,
      \gic0.gc0.count_d1_reg[3]\(3 downto 0) => wr_pntr_plus1(3 downto 0),
